/**
 * Merging on-device (guest) data into a signed-in account. Pure planning only.
 * Both sides are kept: stable ids de-duplicate, cloud conflicts are preserved,
 * and the records generated by older app versions are never uploaded.
 */
import { normalizePrefs } from '@/tracker/features/calendar/calendar';
import { DEFAULT_CALENDAR_PREFS } from '@/tracker/types/calendar';
import { DEFAULT_SETTINGS, DEMO_SETTINGS, type DemoDb } from '@/tracker/lib/api/mock/seed';
import { isLegacySeedId } from '@/tracker/lib/api/mock/legacy-records';
import type { UserSettings } from '@/tracker/types/domain';
import { getEntity, keyOf, snapshotEntities, stableJson, type Kind } from './entities';

export { isLegacySeedId } from '@/tracker/lib/api/mock/legacy-records';

export interface Counts { meals: number; transactions: number; weighIns: number; chats: number; calendarEvents: number }
export const countsOf = (db: DemoDb): Counts => ({
  meals: db.meals.length, transactions: db.transactions.length, weighIns: db.weighIns.length, chats: db.sessions.length, calendarEvents: (db.calendarEvents ?? []).filter((e) => e.origin === 'app').length,
});
export const totalOf = (c: Counts): number => c.meals + c.transactions + c.weighIns + c.chats + c.calendarEvents;

export interface MergePlan {
  add: Array<{ kind: Kind; id: string; data: unknown }>;
  identical: number;
  differing: Array<{ kind: Kind; id: string; guestJson: string }>;
  skippedLegacy: number;
}

const MERGE_KINDS: Kind[] = ['chatSession', 'meal', 'transaction', 'weighIn', 'chatMessage', 'calendarEvent'];
const SETTING_KEYS = Object.keys(DEFAULT_SETTINGS) as Array<keyof UserSettings>;

/** Preserve fields the user actually changed, not untouched legacy/default values. */
function changedSettings(settings: UserSettings): Partial<UserSettings> {
  const patch: Partial<UserSettings> = {};
  for (const key of SETTING_KEYS) {
    const value = settings[key];
    const json = stableJson(value);
    if (json !== stableJson(DEMO_SETTINGS[key]) && json !== stableJson(DEFAULT_SETTINGS[key])) {
      Object.assign(patch, { [key]: value });
    }
  }
  return patch;
}

export function planMerge(guest: DemoDb, account: DemoDb, opts: { accountHasCloudSettings: boolean; accountHasCloudPrefs: boolean }): MergePlan {
  const plan: MergePlan = { add: [], identical: 0, differing: [], skippedLegacy: 0 };
  const have = snapshotEntities(account);
  for (const [key, e] of snapshotEntities(guest)) {
    if (!MERGE_KINDS.includes(e.kind)) continue;
    if (e.kind === 'calendarEvent' && (getEntity(guest, 'calendarEvent', e.id) as { origin?: string }).origin === 'google') continue;
    if (isLegacySeedId(e.id)) {
      plan.skippedLegacy++;
      continue;
    }
    const mine = have.get(key);
    if (!mine) plan.add.push({ kind: e.kind, id: e.id, data: getEntity(guest, e.kind, e.id)! });
    else if (mine.json === e.json) plan.identical++;
    else plan.differing.push({ kind: e.kind, id: e.id, guestJson: e.json });
  }

  // Cloud settings win when present. Otherwise merge only fields that differ
  // from both the old seeded values and today's neutral defaults.
  const settings = changedSettings(guest.settings);
  if (!opts.accountHasCloudSettings && Object.keys(settings).length > 0) {
    plan.add.push({ kind: 'settings', id: 'settings', data: { ...account.settings, ...settings, email: account.settings.email } });
  }
  const guestPrefs = normalizePrefs(guest.calendarPrefs);
  if (!opts.accountHasCloudPrefs && stableJson(guestPrefs) !== stableJson(DEFAULT_CALENDAR_PREFS)) {
    plan.add.push({ kind: 'calendarPrefs', id: 'prefs', data: guestPrefs });
  }
  return plan;
}

export interface MergePreview {
  local: Counts;
  cloud: Counts;
  /** Known records generated by older app versions; always excluded. */
  legacy: Counts;
  willAdd: number;
  identical: number;
  differing: number;
  skippedLegacy: number;
}

export function previewMerge(guest: DemoDb, account: DemoDb, opts: { accountHasCloudSettings: boolean; accountHasCloudPrefs: boolean }): MergePreview {
  const plan = planMerge(guest, account, opts);
  const legacyDb = {
    ...guest,
    meals: guest.meals.filter((x) => isLegacySeedId(x.id)),
    transactions: guest.transactions.filter((x) => isLegacySeedId(x.id)),
    weighIns: guest.weighIns.filter((x) => isLegacySeedId(x.id)),
    sessions: [],
    calendarEvents: [],
  };
  return {
    local: countsOf(guest),
    cloud: countsOf(account),
    legacy: countsOf(legacyDb),
    willAdd: plan.add.filter((a) => a.kind !== 'settings' && a.kind !== 'calendarPrefs').length,
    identical: plan.identical,
    differing: plan.differing.length,
    skippedLegacy: plan.skippedLegacy,
  };
}

export { keyOf };
